m - from start of text\\n    .replace(/-+$/, \\"\\") // Trim - from end of text\\n\\n  if (typeof separator !== \\"undefined\\" && separator !== \\"-\\") {\\n    text = text.replace(/-/g, separator)\\n  }\\n\\n  return text\\n}\\n\\n\\nmodule.exports = async function (data) {\\n\\tconst text = data.$trigger.payload.title;\\n    \\n    if(!text) {\\n        return data.$trigger.payload\\n    }\\n\\n\\tconst slug = slugify(text);\\n\\n\\treturn {...data.$trigger.payload, slug};\\n};"}}],"data":{"$trigger":{"payload":{"tiles":{"create":[],"update":[{"sort":1,"id":28,"collection":"tiles","item":{"id":"594a639c-e9a1-413a-8a32-4d15ea4aa904"}},{"sort":2,"id":40,"collection":"tiles","item":{"id":"78f9e6fe-bf68-439b-8cf3-e382e387e06e"}},{"sort":3,"id":39,"collection":"tiles","item":{"id":"5a31e1ca-6de5-4807-b77a-af790d1faa2a"}},{"sort":4,"id":35,"collection":"survey","item":{"id":"35aa70c7-5755-4e10-ad57-4b8fc034e51b"}},{"sort":5,"id":45,"collection":"tiles","item":{"id":"938716de-500c-45e9-8dd3-23e0f55b0a7b"}}],"delete":[]}},"event":"collections.items.update","keys":["5079ef9b-a298-432a-b02c-4d35d13703d8"],"collection":"collections"},"$last":{"tiles":{"create":[],"update":[{"sort":1,"id":28,"collection":"tiles","item":{"id":"594a639c-e9a1-413a-8a32-4d15ea4aa904"}},{"sort":2,"id":40,"collection":"tiles","item":{"id":"78f9e6fe-bf68-439b-8cf3-e382e387e06e"}},{"sort":3,"id":39,"collection":"tiles","item":{"id":"5a31e1ca-6de5-4807-b77a-af790d1faa2a"}},{"sort":4,"id":35,"collection":"survey","item":{"id":"35aa70c7-5755-4e10-ad57-4b8fc034e51b"}},{"sort":5,"id":45,"collection":"tiles","item":{"id":"938716de-500c-45e9-8dd3-23e0f55b0a7b"}}],"delete":[]}},"$accountability":{"user":"be4995d6-7f36-4988-a920-727042375481","role":"c118c884-0d7f-444f-a349-21228445e5f2","admin":true,"app":true,"ip":"88.130.48.11","userAgent":"Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:109.0) Gecko/20100101 Firefox/113.0","origin":"https://cms.klimadashboard-ms.reedu.de"},"$env":{},"exec_35zs0":{"tiles":{"cr