- from start of text\\n    .replace(/-+$/, \\"\\") // Trim - from end of text\\n\\n  if (typeof separator !== \\"undefined\\" && separator !== \\"-\\") {\\n    text = text.replace(/-/g, separator)\\n  }\\n\\n  return text\\n}\\n\\n\\nmodule.exports = async function (data) {\\n\\tconst text = data.$trigger.payload.title;\\n    \\n    if(!text) {\\n        return data.$trigger.payload\\n    }\\n\\n\\tconst slug = slugify(text);\\n\\n\\treturn {...data.$trigger.payload, slug};\\n};"}}],"data":{"$trigger":{"payload":{"tiles":{"create":[{"collections_id":"cc4ea1d6-1d65-4f12-b36a-0b6e7e8c6122","collection":"successStory","item":{"id":"e03fe167-76be-4ee1-811f-811c20f69a0e"}}],"update":[],"delete":[]}},"event":"collections.items.update","keys":["cc4ea1d6-1d65-4f12-b36a-0b6e7e8c6122"],"collection":"collections"},"$last":{"tiles":{"create":[{"collections_id":"cc4ea1d6-1d65-4f12-b36a-0b6e7e8c6122","collection":"successStory","item":{"id":"e03fe167-76be-4ee1-811f-811c20f69a0e"}}],"update":[],"delete":[]}},"$accountability":{"user":"fe613aab-36e1-48c2-8b49-1cd3c1a34ddf","role":"c118c884-0d7f-444f-a349-21228445e5f2","admin":true,"app":true,"ip":"37.201.119.33","userAgent":"Mozilla/5.0 (Macintosh; Intel Mac OS X 10.15; rv:109.0) Gecko/20100101 Firefox/113.0","origin":"https://cms.klimadashboard-ms.reedu.de"},"$env":{},"exec_35zs0":{"tiles":{"create":[{"collections_id":"cc4ea1d6-1d65-4f12-b36a-0b6e7e8c6122","collection":"successStory","item":{"id":"e03fe167-76be-4ee1-811f-811c20f69a0e"}}],"update":[],"delete":[]}}}}	\N	\N	\N
