783	851	directus_flows	cacf9b28-b8ab-4f4f-b412-64ec988b9f5f	{"steps":[{"operation":"f4c8d580-ce19-4afe-9b4b-6280dd8271f5","key":"exec_35zs0","status":"resolve","options":{"code":"function slugify(text, separator) {\\n  text = text.toString().toLowerCase().trim()\\n\\n  const sets = [\\n    { to: \\"a\\", from: \\"[ÀÁÂÃÅÆĀĂĄẠẢẤẦẨẪẬẮẰẲẴẶ]\\" },\\n    { to: \\"ae\\", from: \\"[Ä]\\" },\\n    { to: \\"c\\", from: \\"[ÇĆĈČ]\\" },\\n    { to: \\"d\\", from: \\"[ÐĎĐÞ]\\" },\\n    { to: \\"e\\", from: \\"[ÈÉÊËĒĔĖĘĚẸẺẼẾỀỂỄỆ]\\" },\\n    { to: \\"g\\", from: \\"[ĜĞĢǴ]\\" },\\n    { to: \\"h\\", from: \\"[ĤḦ]\\" },\\n    { to: \\"i\\", from: \\"[ÌÍÎÏĨĪĮİỈỊ]\\" },\\n    { to: \\"j\\", from: \\"[Ĵ]\\" },\\n    { to: \\"ij\\", from: \\"[Ĳ]\\" },\\n    { to: \\"k\\", from: \\"[Ķ]\\" },\\n    { to: \\"l\\", from: \\"[ĹĻĽŁ]\\" },\\n    { to: \\"m\\", from: \\"[Ḿ]\\" },\\n    { to: \\"n\\", from: \\"[ÑŃŅŇ]\\" },\\n    { to: \\"o\\", from: \\"[ÒÓÔÕØŌŎŐỌỎỐỒỔỖỘỚỜỞỠỢǪǬƠ]\\" },\\n    { to: \\"oe\\", from: \\"[ŒÖ]\\" },\\n    { to: \\"p\\", from: \\"[ṕ]\\" },\\n    { to: \\"r\\", from: \\"[ŔŖŘ]\\" },\\n    { to: \\"s\\", from: \\"[ŚŜŞŠ]\\" },\\n    { to: \\"ss\\", from: \\"[ß]\\" },\\n    { to: \\"t\\", from: \\"[ŢŤ]\\" },\\n    { to: \\"u\\", from: \\"[ÙÚÛŨŪŬŮŰŲỤỦỨỪỬỮỰƯ]\\" },\\n    { to: \\"ue\\", from: \\"[Ü]\\" },\\n    { to: \\"w\\", from: \\"[ẂŴẀẄ]\\" },\\n    { to: \\"x\\", from: \\"[ẍ]\\" },\\n    { to: \\"y\\", from: \\"[ÝŶŸỲỴỶỸ]\\" },\\n    { to: \\"z\\", from: \\"[ŹŻŽ]\\" },\\n    { to: \\"-\\", from: \\"[·/_,:;']\\" },\\n  ]\\n\\n  sets.forEach((set) => {\\n    text = text.replace(new RegExp(set.from, \\"gi\\"), set.to)\\n  })\\n\\n  text = text\\n    .toString()\\n    .toLowerCase()\\n    .replace(/\\\\s+/g, \\"-\\") // Replace spaces with -\\n    .replace(/&/g, \\"-and-\\") // Replace & with 'and'\\n    .replace(/[^\\\\w\\\\-]+/g, \\"\\") // Remove all non-word chars\\n    .replace(/\\\\--+/g, \\"-\\") // Replace multiple - with single -\\n    .replace(/^-+/, \\"\\") // Trim 